-- 001_baseline.sql — squashed snapshot of migrations 010–464 (2026-09-03).
-- Generated by running the full delta chain on a scratch DB; do not hand-edit
-- without regenerating. Idempotent by construction (IF NOT EXISTS / OR IGNORE)
-- so it no-ops on already-migrated databases and records a single tracker row.
-- New migrations continue from 002_. Delta history: git tag schema-pre-squash.
CREATE TABLE IF NOT EXISTS schema_migrations (
                    name TEXT PRIMARY KEY,
                    applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE IF NOT EXISTS calendars (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    description TEXT,
    color TEXT,
    is_default INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    deleted_at TEXT
, metadata TEXT);
CREATE INDEX IF NOT EXISTS idx_calendars_deleted_at ON calendars(deleted_at);
CREATE TABLE IF NOT EXISTS events (
    id TEXT PRIMARY KEY,
    calendar_id TEXT NOT NULL REFERENCES calendars(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    description TEXT,
    agenda TEXT,
    venue TEXT,
    start_time TEXT NOT NULL,
    end_time TEXT NOT NULL,
    timezone TEXT NOT NULL,
    is_all_day INTEGER NOT NULL DEFAULT 0,
    recurrence_rule TEXT,
    status TEXT NOT NULL CHECK (status IN ('tentative', 'confirmed', 'cancelled')),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_events_calendar_id ON events(calendar_id);
CREATE INDEX IF NOT EXISTS idx_events_start_time ON events(start_time);
CREATE INDEX IF NOT EXISTS idx_events_deleted_at ON events(deleted_at);
CREATE TABLE IF NOT EXISTS event_recipients (
    id TEXT PRIMARY KEY,
    event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
    recipient_type TEXT NOT NULL CHECK (recipient_type IN ('email', 'phone', 'channel')),
    recipient_address TEXT NOT NULL,
    name TEXT,
    status TEXT NOT NULL CHECK (status IN ('pending', 'confirmed', 'declined', 'tentative')),
    responded_at TEXT,
    notes TEXT
);
CREATE INDEX IF NOT EXISTS idx_event_recipients_event_id ON event_recipients(event_id);
CREATE TABLE IF NOT EXISTS webhook_configs (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    url TEXT NOT NULL,
    secret TEXT NOT NULL,  -- For HMAC signature
    events TEXT NOT NULL,  -- JSON array of event types
    retry_count INTEGER NOT NULL DEFAULT 3,
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_webhook_configs_active ON webhook_configs(is_active);
CREATE INDEX IF NOT EXISTS idx_webhook_configs_deleted_at ON webhook_configs(deleted_at);
CREATE TABLE IF NOT EXISTS webhook_deliveries (
    id TEXT PRIMARY KEY,
    webhook_id TEXT NOT NULL REFERENCES webhook_configs(id),
    event TEXT NOT NULL,
    payload TEXT NOT NULL,  -- JSON payload sent
    status TEXT NOT NULL CHECK (status IN ('pending', 'delivered', 'failed')),
    response_code INTEGER,
    response_body TEXT,
    error_message TEXT,
    attempt_count INTEGER NOT NULL DEFAULT 0,
    next_retry_at TEXT,
    created_at TEXT NOT NULL,
    delivered_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_webhook_id ON webhook_deliveries(webhook_id);
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_status ON webhook_deliveries(status);
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_event ON webhook_deliveries(event);
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_created_at ON webhook_deliveries(created_at);
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_next_retry ON webhook_deliveries(next_retry_at) WHERE status = 'pending';
CREATE TABLE IF NOT EXISTS email_inboxes (
    id TEXT PRIMARY KEY,
    agentmail_inbox_id TEXT NOT NULL UNIQUE,
    display_name TEXT NOT NULL,
    email_address TEXT NOT NULL,
    is_active INTEGER NOT NULL DEFAULT 1,
    last_polled_at TEXT,
    metadata TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_email_inboxes_agentmail_id ON email_inboxes(agentmail_inbox_id);
CREATE INDEX IF NOT EXISTS idx_email_inboxes_active ON email_inboxes(is_active);
CREATE INDEX IF NOT EXISTS idx_email_inboxes_deleted_at ON email_inboxes(deleted_at);
CREATE TABLE IF NOT EXISTS email_messages (
    id TEXT PRIMARY KEY,
    inbox_id TEXT NOT NULL REFERENCES email_inboxes(id),
    agentmail_message_id TEXT NOT NULL UNIQUE,
    thread_id TEXT NOT NULL,
    subject TEXT,
    sender_email TEXT NOT NULL,
    sender_name TEXT,
    to_addresses TEXT,
    cc_addresses TEXT,
    text_body TEXT,
    html_body TEXT,
    preview TEXT,
    labels TEXT,
    has_attachments INTEGER NOT NULL DEFAULT 0,
    in_reply_to TEXT,
    message_timestamp TEXT NOT NULL,
    processed_at TEXT,
    created_at TEXT NOT NULL
, attachments_json TEXT);
CREATE INDEX IF NOT EXISTS idx_email_messages_inbox ON email_messages(inbox_id);
CREATE INDEX IF NOT EXISTS idx_email_messages_thread ON email_messages(thread_id);
CREATE INDEX IF NOT EXISTS idx_email_messages_agentmail_id ON email_messages(agentmail_message_id);
CREATE INDEX IF NOT EXISTS idx_email_messages_sender ON email_messages(sender_email);
CREATE INDEX IF NOT EXISTS idx_email_messages_timestamp ON email_messages(message_timestamp);
CREATE TABLE IF NOT EXISTS email_threads (
    id TEXT PRIMARY KEY,
    inbox_id TEXT NOT NULL REFERENCES email_inboxes(id),
    agentmail_thread_id TEXT NOT NULL,
    subject TEXT,
    contact_id TEXT REFERENCES contacts(id),
    session_key TEXT NOT NULL,
    message_count INTEGER NOT NULL DEFAULT 0,
    last_message_at TEXT,
    is_active INTEGER NOT NULL DEFAULT 1,
    metadata TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT, agenda TEXT, origin_session_key TEXT,
    UNIQUE(inbox_id, agentmail_thread_id)
);
CREATE INDEX IF NOT EXISTS idx_email_threads_inbox ON email_threads(inbox_id);
CREATE INDEX IF NOT EXISTS idx_email_threads_contact ON email_threads(contact_id);
CREATE INDEX IF NOT EXISTS idx_email_threads_session_key ON email_threads(session_key);
CREATE INDEX IF NOT EXISTS idx_email_threads_active ON email_threads(is_active);
CREATE INDEX IF NOT EXISTS idx_email_threads_deleted_at ON email_threads(deleted_at);
CREATE TABLE IF NOT EXISTS llm_call_log (
    id TEXT PRIMARY KEY,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    provider TEXT NOT NULL,
    model TEXT NOT NULL DEFAULT '',
    call_category TEXT NOT NULL,
    session_key TEXT,
    system_prompt TEXT NOT NULL DEFAULT '',
    user_message TEXT NOT NULL DEFAULT '',
    messages_json TEXT,
    response_text TEXT NOT NULL DEFAULT '',
    latency_seconds REAL,
    ttft_seconds REAL,
    prompt_tokens INTEGER,
    completion_tokens INTEGER,
    total_tokens INTEGER,
    cached_tokens INTEGER,
    status TEXT NOT NULL DEFAULT 'completed',
    error_message TEXT,
    project_id TEXT,
    task_id TEXT,
    dispatch_id TEXT
, tools_json TEXT, contact_id TEXT, tool_blocks_json TEXT);
CREATE INDEX IF NOT EXISTS idx_llm_call_log_created ON llm_call_log(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_llm_call_log_provider ON llm_call_log(provider, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_llm_call_log_category ON llm_call_log(call_category, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_llm_call_log_session ON llm_call_log(session_key);
CREATE INDEX IF NOT EXISTS idx_llm_call_log_dispatch ON llm_call_log(dispatch_id);
CREATE INDEX IF NOT EXISTS idx_llm_call_log_project ON llm_call_log(project_id);
CREATE TRIGGER IF NOT EXISTS llm_call_log_cleanup
AFTER INSERT ON llm_call_log
BEGIN
    DELETE FROM llm_call_log WHERE created_at < datetime('now', '-90 days');
END;
CREATE TABLE IF NOT EXISTS eval_runs (
    id TEXT PRIMARY KEY,
    started_at TEXT NOT NULL DEFAULT (datetime('now')),
    completed_at TEXT,
    category TEXT,
    total_cases INTEGER NOT NULL DEFAULT 0,
    passed_cases INTEGER NOT NULL DEFAULT 0,
    failed_cases INTEGER NOT NULL DEFAULT 0,
    overall_pass_rate REAL,
    status TEXT NOT NULL DEFAULT 'running'
);
CREATE INDEX IF NOT EXISTS idx_eval_runs_started ON eval_runs(started_at DESC);
CREATE TABLE IF NOT EXISTS eval_case_results (
    id TEXT PRIMARY KEY,
    run_id TEXT NOT NULL REFERENCES eval_runs(id),
    case_id TEXT NOT NULL,
    category TEXT NOT NULL,
    passed INTEGER NOT NULL DEFAULT 0,
    llm_response TEXT NOT NULL DEFAULT '',
    llm_latency_seconds REAL,
    judge_score REAL,
    judge_reasoning TEXT,
    structural_results_json TEXT,
    error_message TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
, input_messages_json TEXT);
CREATE INDEX IF NOT EXISTS idx_eval_case_results_run ON eval_case_results(run_id);
CREATE INDEX IF NOT EXISTS idx_eval_case_results_case ON eval_case_results(case_id, created_at DESC);
CREATE TABLE IF NOT EXISTS skill_delegations (
    id TEXT PRIMARY KEY,
    session_key TEXT NOT NULL,
    user_story TEXT NOT NULL,
    plan TEXT,
    claude_session_id TEXT,
    status TEXT NOT NULL DEFAULT 'draft',
    files_created_json TEXT,
    result_summary TEXT,
    cost_usd REAL,
    error_message TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_llm_call_log_contact
ON llm_call_log(contact_id) WHERE contact_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS memory_search_log (
    id TEXT PRIMARY KEY,
    query TEXT NOT NULL,
    results_json TEXT NOT NULL DEFAULT '[]',
    session_key TEXT,
    result_count INTEGER NOT NULL DEFAULT 0,
    latency_seconds REAL,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_memory_search_log_created ON memory_search_log(created_at DESC);
CREATE TABLE IF NOT EXISTS subagents (
    id TEXT PRIMARY KEY,
    parent_session_key TEXT NOT NULL,
    session_key TEXT NOT NULL UNIQUE,
    task TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'created',
    result TEXT,
    error_message TEXT,
    agent_type TEXT NOT NULL DEFAULT 'claude',
    claude_session_id TEXT,
    cost_usd REAL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
, persona INTEGER NOT NULL DEFAULT 0, model TEXT NOT NULL DEFAULT '', contact_id TEXT, modality TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_subagents_parent
    ON subagents(parent_session_key, status);
CREATE TABLE IF NOT EXISTS whatsappgroups (
    id TEXT PRIMARY KEY,
    whatsapp_jid TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL DEFAULT '',
    description TEXT,
    member_count INTEGER NOT NULL DEFAULT 0,
    metadata TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
, memory_entity_id TEXT);
CREATE INDEX IF NOT EXISTS idx_whatsappgroups_whatsapp_jid ON whatsappgroups(whatsapp_jid);
CREATE INDEX IF NOT EXISTS idx_whatsappgroups_name ON whatsappgroups(name);
CREATE INDEX IF NOT EXISTS idx_whatsappgroups_deleted_at ON whatsappgroups(deleted_at);
CREATE TABLE IF NOT EXISTS whatsappgroup_members (
    id TEXT PRIMARY KEY,
    group_id TEXT NOT NULL REFERENCES whatsappgroups(id),
    contact_id TEXT NOT NULL REFERENCES contacts(id),
    is_admin INTEGER NOT NULL DEFAULT 0,
    is_super_admin INTEGER NOT NULL DEFAULT 0,
    display_name TEXT NOT NULL DEFAULT '',
    joined_at TEXT NOT NULL,
    left_at TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE(group_id, contact_id)
);
CREATE INDEX IF NOT EXISTS idx_whatsappgroup_members_group_id ON whatsappgroup_members(group_id);
CREATE INDEX IF NOT EXISTS idx_whatsappgroup_members_contact_id ON whatsappgroup_members(contact_id);
CREATE TABLE IF NOT EXISTS memory_entity_relations (
    source_entity_id TEXT NOT NULL,
    category TEXT NOT NULL,
    target_entity_id TEXT NOT NULL,
    PRIMARY KEY (source_entity_id, category, target_entity_id),
    FOREIGN KEY (source_entity_id) REFERENCES memory_entities(entity_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_memory_entity_relations_target
    ON memory_entity_relations(target_entity_id);
CREATE TABLE IF NOT EXISTS memory_aliases (
    alias TEXT PRIMARY KEY,
    entity_id TEXT NOT NULL,
    FOREIGN KEY (entity_id) REFERENCES memory_entities(entity_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_memory_aliases_entity
    ON memory_aliases(entity_id);
CREATE TABLE IF NOT EXISTS "contacts" (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    phone_number TEXT UNIQUE,
    email TEXT UNIQUE,
    metadata TEXT,
    is_default INTEGER NOT NULL DEFAULT 0,
    is_trusted INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
, allow_inbound_dm INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS idx_contacts_phone_number ON contacts(phone_number) WHERE phone_number IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_contacts_email ON contacts(email) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_contacts_name ON contacts(name);
CREATE INDEX IF NOT EXISTS idx_contacts_deleted_at ON contacts(deleted_at);
CREATE TABLE IF NOT EXISTS memory_claim_types (
    key TEXT PRIMARY KEY,
    applicable_types TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    example TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS "memory_claims" (
    id TEXT PRIMARY KEY,
    claim_type_key TEXT NOT NULL,
    subject_id TEXT NOT NULL,
    object_id TEXT,
    value TEXT,
    status TEXT NOT NULL DEFAULT 'active'
        CHECK(status IN ('active','superseded','retracted','expired',
                         'disputed','archived','redundant','disproven','obsolete')),
    visibility TEXT NOT NULL DEFAULT 'channel'
        CHECK(visibility IN ('private','contact','group','channel','public')),
    scope TEXT NOT NULL DEFAULT '[]',
    created_at TEXT NOT NULL,
    superseded_by TEXT NOT NULL DEFAULT '[]',
    source_messages TEXT NOT NULL DEFAULT '[]',
    CHECK((object_id IS NOT NULL) + (value IS NOT NULL AND value != '') <= 1),
    FOREIGN KEY (claim_type_key) REFERENCES memory_claim_types(key)
);
CREATE INDEX IF NOT EXISTS idx_memory_claims_subject
    ON memory_claims(subject_id);
CREATE INDEX IF NOT EXISTS idx_memory_claims_object
    ON memory_claims(object_id);
CREATE INDEX IF NOT EXISTS idx_memory_claims_status
    ON memory_claims(status);
CREATE INDEX IF NOT EXISTS idx_memory_claims_type
    ON memory_claims(claim_type_key);
CREATE VIRTUAL TABLE IF NOT EXISTS memory_entities_fts USING fts5(
    entity_id,
    display_name,
    rendered_body
);
CREATE TABLE IF NOT EXISTS 'memory_entities_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE IF NOT EXISTS 'memory_entities_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS 'memory_entities_fts_content'(id INTEGER PRIMARY KEY, c0, c1, c2);
CREATE TABLE IF NOT EXISTS 'memory_entities_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE IF NOT EXISTS 'memory_entities_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE VIRTUAL TABLE IF NOT EXISTS memory_entity_embeddings
USING vec0(
    entity_id TEXT PRIMARY KEY,
    embedding float[1536]
);
CREATE TABLE IF NOT EXISTS "memory_entity_embeddings_info" (key text primary key, value any);
CREATE TABLE IF NOT EXISTS "memory_entity_embeddings_chunks"(chunk_id INTEGER PRIMARY KEY AUTOINCREMENT,size INTEGER NOT NULL,validity BLOB NOT NULL,rowids BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS "memory_entity_embeddings_rowids"(rowid INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,chunk_id INTEGER,chunk_offset INTEGER);
CREATE TABLE IF NOT EXISTS "memory_entity_embeddings_vector_chunks00"(rowid PRIMARY KEY,vectors BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS memory_questions (
    id TEXT PRIMARY KEY,
    entity_id TEXT NOT NULL,
    question TEXT NOT NULL,
    options TEXT,          -- JSON array of suggested answers
    context TEXT,          -- what conflict triggered this question
    status TEXT NOT NULL DEFAULT 'open',  -- open, answered, dismissed
    answer TEXT,
    answer_claim_id TEXT,
    created_at TEXT NOT NULL,
    answered_at TEXT
);
CREATE TABLE IF NOT EXISTS routines (
    id TEXT PRIMARY KEY,
    session_key TEXT NOT NULL,
    name TEXT NOT NULL,
    schedule TEXT NOT NULL,
    prompt TEXT NOT NULL,
    enabled INTEGER NOT NULL DEFAULT 1,
    next_run_at TEXT NOT NULL,
    last_run_at TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now')), timezone TEXT, valid_from TEXT, valid_until TEXT,
    UNIQUE(session_key, name)
);
CREATE TABLE IF NOT EXISTS persona_records (
    id          TEXT PRIMARY KEY,
    revision    INTEGER NOT NULL UNIQUE,
    soul        TEXT NOT NULL DEFAULT '',
    identity    TEXT NOT NULL DEFAULT '',
    agents      TEXT NOT NULL DEFAULT '',
    user_content TEXT NOT NULL DEFAULT '',
    config      TEXT NOT NULL DEFAULT '{}',
    is_active   INTEGER NOT NULL DEFAULT 0,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX IF NOT EXISTS idx_persona_records_active ON persona_records(is_active);
CREATE TABLE IF NOT EXISTS recon_model_overrides (
    entity_id TEXT PRIMARY KEY,
    model     TEXT NOT NULL,
    reason    TEXT NOT NULL DEFAULT '',
    set_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_memory_claims_type_value_status
    ON memory_claims(claim_type_key, value, status);
CREATE TABLE IF NOT EXISTS memory_extraction_turns (
    id             TEXT PRIMARY KEY,
    session_key    TEXT NOT NULL,
    message_id     TEXT NOT NULL,
    ran_at         TEXT NOT NULL,
    claims_created INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_memory_extraction_turns_session
    ON memory_extraction_turns(session_key, ran_at DESC);
CREATE TABLE IF NOT EXISTS "memory_entities" (
    entity_id TEXT PRIMARY KEY,
    entity_type TEXT NOT NULL
        CHECK(entity_type IN ('person','group','location','trip','stay',
                              'event','task','file','thing','decision','connection',
                              'attraction','dayplan','self','relationship','daylog')),
    display_name TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT 'active'
        CHECK(status IN ('active','archived','deprecated')),
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now')),
    last_reconciled_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_memory_entities_type
    ON memory_entities(entity_type);
CREATE INDEX IF NOT EXISTS idx_memory_entities_display_name
    ON memory_entities(display_name);
CREATE TABLE IF NOT EXISTS location_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    fetched_at TEXT NOT NULL,                       -- when Bob queried HA (ISO UTC)
    device_tracker_entity_id TEXT NOT NULL,
    latitude REAL,
    longitude REAL,
    gps_accuracy REAL,                              -- meters, nullable
    zone_state TEXT,                                -- 'home' / 'not_home' / zone name
    battery_level REAL,                             -- nullable
    ha_last_updated TEXT,                           -- when HA last got data from phone
    raw_attributes TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX IF NOT EXISTS idx_location_history_fetched
    ON location_history(fetched_at DESC);
CREATE INDEX IF NOT EXISTS idx_location_history_device_time
    ON location_history(device_tracker_entity_id, fetched_at DESC);
CREATE TABLE IF NOT EXISTS voice_sessions (
    id TEXT PRIMARY KEY,
    origin_session_key TEXT NOT NULL,
    voice TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT 'pending',   -- pending | active | completed | expired
    transcript TEXT NOT NULL DEFAULT '',
    duration_seconds REAL,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    activated_at TEXT,
    completed_at TEXT
, goal TEXT NOT NULL DEFAULT '', report_back_session_key TEXT, subagent_id TEXT, outcome TEXT);
CREATE TABLE IF NOT EXISTS "phone_calls" (
    id TEXT PRIMARY KEY,
    call_sid TEXT,
    stream_sid TEXT,
    phone_number TEXT,
    direction TEXT NOT NULL DEFAULT 'outbound'
        CHECK (direction IN ('inbound', 'outbound', 'voice_link')),
    status TEXT NOT NULL DEFAULT 'active'
        CHECK (status IN ('ringing', 'active', 'completed', 'failed', 'canceled', 'busy', 'no-answer')),
    agenda TEXT NOT NULL DEFAULT '',
    exchange_count INTEGER NOT NULL DEFAULT 0,
    duration_seconds REAL,
    recording_path TEXT,
    started_at TEXT NOT NULL,
    completed_at TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at TEXT NOT NULL DEFAULT (datetime('now')),
    origin_session_key TEXT,
    engine TEXT NOT NULL DEFAULT 'default',
    transcript TEXT NOT NULL DEFAULT '',
    realtime_meta TEXT NOT NULL DEFAULT '{}',
    subagent_id TEXT,
    result_dispatched_at TEXT,
    outcome TEXT
);
CREATE TABLE IF NOT EXISTS dream_runs (
    id TEXT PRIMARY KEY,                    -- dream-YYYY-MM-DD-hex8
    started_at TEXT NOT NULL,
    finished_at TEXT,
    window_start TEXT NOT NULL,             -- descriptive only; coverage is per-session cursors
    window_end TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('running','complete','failed')),
    trigger TEXT NOT NULL CHECK (trigger IN ('heartbeat','manual','cli')),
    model TEXT NOT NULL DEFAULT '',
    sessions_reviewed_json TEXT NOT NULL DEFAULT '[]',
    stats_json TEXT NOT NULL DEFAULT '{}',
    journal_text TEXT NOT NULL DEFAULT '',
    error TEXT
);
CREATE TABLE IF NOT EXISTS dream_resolutions (
    id TEXT PRIMARY KEY,                    -- resolution-hex8
    title TEXT NOT NULL,
    behaviour TEXT NOT NULL,                -- the observable behaviour, good or bad
    trigger_condition TEXT NOT NULL,        -- when/where it applies
    success_signal TEXT NOT NULL,           -- what a future dream checks to mark kept
    status TEXT NOT NULL CHECK (status IN
        ('draft','open','in_program','kept','dropped','stale')),
    first_seen_at TEXT NOT NULL,
    last_seen_at TEXT NOT NULL,
    observation_count INTEGER NOT NULL DEFAULT 1,
    evidence_json TEXT NOT NULL DEFAULT '[]', -- [{run_id, session_key, line, excerpt, kind}]
    source_run_id TEXT NOT NULL REFERENCES dream_runs(id),
    program_id TEXT                         -- reserved for future improvement programs
);
CREATE TABLE IF NOT EXISTS dream_plans (
    id TEXT PRIMARY KEY,                    -- plan-hex8
    title TEXT NOT NULL,
    what_was_discussed TEXT NOT NULL,
    proposed_action TEXT NOT NULL,          -- the concrete next step for the human(s)
    assistance_method TEXT NOT NULL,        -- how Bob can assist, grounded in real tools
    autonomy_tier INTEGER NOT NULL DEFAULT 1 CHECK (autonomy_tier IN (1,2)),
    status TEXT NOT NULL CHECK (status IN
        ('draft','proposed','approved','actioned','completed','expired','dismissed')),
    approved_by TEXT,                       -- 'operator' | 'auto' | NULL
    approved_at TEXT,
    announced_at TEXT,                      -- NULL until announced in its evidence session
    reannounced_at TEXT,                    -- set when the single follow-up is spent
    evidence_json TEXT NOT NULL DEFAULT '[]',
    source_run_id TEXT NOT NULL REFERENCES dream_runs(id),
    due_hint TEXT,                          -- free-text/date from conversation, if any
    task_id TEXT,                           -- reserved; no execution engine exists today
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS dream_item_links (
    item_type TEXT NOT NULL CHECK (item_type IN ('resolution','plan')),
    item_id TEXT NOT NULL,
    session_key TEXT,
    entity_id TEXT                          -- person-*/group-* memory entities
);
CREATE INDEX IF NOT EXISTS idx_dream_links_entity ON dream_item_links(entity_id, item_type);
CREATE INDEX IF NOT EXISTS idx_dream_links_session ON dream_item_links(session_key, item_type);
CREATE INDEX IF NOT EXISTS idx_dream_links_item ON dream_item_links(item_type, item_id);
CREATE TABLE IF NOT EXISTS dream_session_review (
    session_key TEXT PRIMARY KEY,
    last_reviewed_message_at TEXT NOT NULL,
    run_id TEXT NOT NULL REFERENCES dream_runs(id),
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS dream_config (
    key TEXT PRIMARY KEY,                   -- e.g. 'auto_approve_plans'
    value TEXT NOT NULL,                    -- JSON-encoded
    updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_dream_resolutions_status ON dream_resolutions(status);
CREATE INDEX IF NOT EXISTS idx_dream_plans_status ON dream_plans(status);
CREATE INDEX IF NOT EXISTS idx_dream_runs_window ON dream_runs(window_end);
CREATE INDEX IF NOT EXISTS idx_dream_plans_pending_announce ON dream_plans(status, announced_at);
CREATE TABLE IF NOT EXISTS dream_deferred_candidates (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    item_type TEXT NOT NULL CHECK (item_type IN ('resolution','plan')),
    session_key TEXT NOT NULL DEFAULT '',
    candidate_json TEXT NOT NULL,           -- full candidate incl. evidence
    created_at TEXT NOT NULL,
    source_run_id TEXT NOT NULL REFERENCES dream_runs(id)
);
CREATE INDEX IF NOT EXISTS idx_dream_deferred_type ON dream_deferred_candidates(item_type, id);
CREATE VIRTUAL TABLE IF NOT EXISTS dream_item_embeddings
USING vec0(
    item_id TEXT PRIMARY KEY,
    embedding float[1536] distance_metric=cosine
);
CREATE TABLE IF NOT EXISTS "dream_item_embeddings_info" (key text primary key, value any);
CREATE TABLE IF NOT EXISTS "dream_item_embeddings_chunks"(chunk_id INTEGER PRIMARY KEY AUTOINCREMENT,size INTEGER NOT NULL,validity BLOB NOT NULL,rowids BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS "dream_item_embeddings_rowids"(rowid INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,chunk_id INTEGER,chunk_offset INTEGER);
CREATE TABLE IF NOT EXISTS "dream_item_embeddings_vector_chunks00"(rowid PRIMARY KEY,vectors BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS event_log (
    id TEXT PRIMARY KEY,
    event_type TEXT NOT NULL,
    schema_version INTEGER NOT NULL DEFAULT 1,
    binding_key TEXT NOT NULL,          -- immutable channel address at ingestion (invariant 3)
    conversation_id TEXT NOT NULL,      -- conversation assigned at ingestion (invariant 3)
    source TEXT NOT NULL,               -- e.g. 'whatsapp', 'email', 'phone', 'heartbeat', 'cron'
    external_id TEXT,                   -- source-native id; uniqueness key when present
    causation_id TEXT,                  -- event id that directly caused this one
    correlation_id TEXT,                -- episode/goal thread id
    occurred_at TEXT NOT NULL,          -- source-claimed time
    recorded_at TEXT NOT NULL,          -- ingestion time
    payload_json TEXT NOT NULL DEFAULT '{}'
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_event_log_source_external
    ON event_log (source, external_id) WHERE external_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_event_log_conversation
    ON event_log (conversation_id, recorded_at);
CREATE INDEX IF NOT EXISTS idx_event_log_type_recorded
    ON event_log (event_type, recorded_at);
CREATE TABLE IF NOT EXISTS turns (
    id TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending',  -- pending|running|succeeded|failed|dead
    input_high_watermark TEXT,               -- max event id fixed before execution (invariant 5)
    lease_owner TEXT,
    lease_expires_at TEXT,
    attempt INTEGER NOT NULL DEFAULT 0,
    started_at TEXT,
    completed_at TEXT,
    error TEXT,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_turns_conversation_status
    ON turns (conversation_id, status);
CREATE UNIQUE INDEX IF NOT EXISTS idx_turns_one_active_per_conversation
    ON turns (conversation_id) WHERE status IN ('pending', 'running');
CREATE TABLE IF NOT EXISTS turn_events (
    turn_id TEXT NOT NULL,
    event_id TEXT NOT NULL,
    PRIMARY KEY (turn_id, event_id)
);
CREATE INDEX IF NOT EXISTS idx_turn_events_event ON turn_events (event_id);
CREATE TABLE IF NOT EXISTS effects (
    id TEXT PRIMARY KEY,
    turn_id TEXT,
    kind TEXT NOT NULL,                      -- e.g. 'whatsapp_send', 'email_send', 'call_place'
    idempotency_key TEXT NOT NULL,
    payload_json TEXT NOT NULL DEFAULT '{}',
    status TEXT NOT NULL DEFAULT 'pending',  -- pending|delivering|delivered|failed|dead
    attempt INTEGER NOT NULL DEFAULT 0,
    available_at TEXT NOT NULL,              -- retry backoff gate
    delivered_at TEXT,
    external_result_id TEXT,
    error TEXT,
    created_at TEXT NOT NULL
, claimed_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS idx_effects_idempotency
    ON effects (idempotency_key);
CREATE INDEX IF NOT EXISTS idx_effects_status_available
    ON effects (status, available_at);
CREATE TABLE IF NOT EXISTS wakeups (
    id TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL,
    goal_id TEXT,
    not_before TEXT NOT NULL,
    recurrence TEXT,                         -- cron-ish spec, NULL = one-shot
    tz TEXT,
    status TEXT NOT NULL DEFAULT 'scheduled', -- scheduled|fired|cancelled
    created_by_turn TEXT,
    created_at TEXT NOT NULL
, kind TEXT NOT NULL DEFAULT 'wake', payload_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS idx_wakeups_due
    ON wakeups (status, not_before);
CREATE TABLE IF NOT EXISTS attention_shadow (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id TEXT,                       -- event_log id of the stimulus (if appended)
    session_key TEXT NOT NULL,           -- conversation/binding key
    source TEXT NOT NULL,                -- whatsapp | email | phone | routine
    chat_kind TEXT,                      -- dm | group | thread
    addressed INTEGER NOT NULL,          -- Tier 0 structural decision
    addressed_reason TEXT,               -- dm | mention_jid | name_variant | reply_to_bot | not_addressed
    proposed_window_ms INTEGER NOT NULL, -- Tier 1 debounce the coordinator would use
    decision TEXT NOT NULL,              -- ACT | WAIT | STAND_DOWN (Tier 0/2 combined; shadow)
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_attention_shadow_session
    ON attention_shadow(session_key, created_at);
CREATE INDEX IF NOT EXISTS idx_attention_shadow_created
    ON attention_shadow(created_at);
CREATE TABLE IF NOT EXISTS goals (
    id TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL,           -- conversation working the goal
    origin_conversation_id TEXT,             -- conversation to wake on completion
    kind TEXT NOT NULL DEFAULT 'task',       -- task|outreach|subagent|call|email_thread
    objective TEXT NOT NULL,
    strategy_json TEXT,
    progress TEXT,
    result TEXT,
    status TEXT NOT NULL DEFAULT 'active',   -- active|completed|failed|cancelled
    version INTEGER NOT NULL DEFAULT 1,
    deadline TEXT,
    external_ref TEXT,                       -- e.g. subagent id, call id, thread id
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
, parent_goal_id TEXT REFERENCES goals(id));
CREATE INDEX IF NOT EXISTS idx_goals_conversation
    ON goals (conversation_id, status);
CREATE INDEX IF NOT EXISTS idx_goals_origin
    ON goals (origin_conversation_id, status);
CREATE INDEX IF NOT EXISTS idx_goals_external_ref
    ON goals (external_ref);
CREATE TABLE IF NOT EXISTS goal_transitions (
    id TEXT PRIMARY KEY,
    goal_id TEXT NOT NULL REFERENCES goals(id),
    from_status TEXT NOT NULL,
    to_status TEXT NOT NULL,
    version INTEGER NOT NULL,
    note TEXT,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_goal_transitions_goal
    ON goal_transitions (goal_id, created_at);
CREATE TABLE IF NOT EXISTS conversations (
    id TEXT PRIMARY KEY,
    kind TEXT NOT NULL DEFAULT 'dm',         -- dm|group|internal
    title TEXT,
    policy_json TEXT,
    merged_into TEXT,                        -- set when this conversation was merged away
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS bindings (
    session_key TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL REFERENCES conversations(id),
    channel TEXT NOT NULL,                   -- whatsapp|email|subagent|internal|voice
    kind TEXT NOT NULL DEFAULT 'thread',     -- identity|thread
    address TEXT,                            -- e.g. email address, phone number
    sensitivity TEXT,
    merged_from TEXT,                        -- original conversation_id before merge
    merged_at TEXT,
    created_at TEXT NOT NULL
, endpoint_kind TEXT, contact_id TEXT, is_active INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS idx_bindings_conversation
    ON bindings (conversation_id);
CREATE TABLE IF NOT EXISTS participants (
    conversation_id TEXT NOT NULL REFERENCES conversations(id),
    identifier TEXT NOT NULL,
    display_name TEXT NOT NULL DEFAULT '',
    contact_id TEXT REFERENCES contacts(id),
    is_trusted INTEGER NOT NULL DEFAULT 0,
    last_active_at TEXT NOT NULL,
    PRIMARY KEY (conversation_id, identifier)
);
CREATE INDEX IF NOT EXISTS idx_participants_contact ON participants(contact_id) WHERE contact_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS agendas (
    conversation_id TEXT PRIMARY KEY REFERENCES conversations(id),
    agenda TEXT NOT NULL DEFAULT '',
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS messages (
    id TEXT PRIMARY KEY,
    conversation_id TEXT NOT NULL,
    binding_key TEXT,
    role TEXT NOT NULL CHECK(role IN ('user', 'assistant', 'system', 'tool')),
    content TEXT NOT NULL,
    sender_id TEXT,
    channel TEXT,
    metadata TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    dispatched INTEGER NOT NULL DEFAULT 1,
    synthetic INTEGER NOT NULL DEFAULT 0,
    tool_summary TEXT,
    tool_blocks_json TEXT,
    provenance TEXT
);
CREATE INDEX IF NOT EXISTS idx_messages_conv_time ON messages(conversation_id, created_at);
CREATE INDEX IF NOT EXISTS idx_messages_conv_time_desc ON messages(conversation_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_messages_channel ON messages(channel);
CREATE INDEX IF NOT EXISTS idx_messages_undispatched
    ON messages(conversation_id, dispatched) WHERE dispatched = 0;
CREATE INDEX IF NOT EXISTS idx_messages_provenance
    ON messages(conversation_id, provenance) WHERE provenance IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_goals_parent ON goals (parent_goal_id, status);
CREATE TABLE IF NOT EXISTS goal_conversations (
    goal_id TEXT NOT NULL REFERENCES goals(id),
    conversation_id TEXT NOT NULL,        -- canonical cid via resolve_cid()
    role TEXT NOT NULL DEFAULT 'holder',  -- holder|origin|worker
    created_at TEXT NOT NULL,
    PRIMARY KEY (goal_id, conversation_id)
);
CREATE INDEX IF NOT EXISTS idx_goal_conversations_cid ON goal_conversations (conversation_id);
CREATE TABLE IF NOT EXISTS memory_entity_mentions (
    entity_id TEXT NOT NULL,
    conversation_id TEXT NOT NULL,        -- canonical cid
    first_message_id TEXT NOT NULL,
    last_message_id TEXT NOT NULL,
    first_at TEXT NOT NULL,
    last_at TEXT NOT NULL,
    PRIMARY KEY (entity_id, conversation_id)
);
CREATE INDEX IF NOT EXISTS idx_memory_entity_mentions_conv ON memory_entity_mentions (conversation_id);
CREATE TABLE IF NOT EXISTS memory_routing_log (
    id TEXT PRIMARY KEY,
    stimulus_id TEXT NOT NULL,            -- e.g. the extraction turn message id
    source_conversation_id TEXT NOT NULL,
    goal_id TEXT NOT NULL,
    claim_ids TEXT NOT NULL DEFAULT '[]',  -- JSON array
    entity_ids TEXT NOT NULL DEFAULT '[]', -- JSON array
    match_type TEXT NOT NULL,             -- ref|mention|participant
    probe_verdict TEXT,                   -- relevant|ignore|skipped|error
    revise_outcome TEXT,                  -- revised|no_change|skipped|error
    wake_decision TEXT,                   -- wake|no_wake|shadow_wake
    detail TEXT,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_memory_routing_log_goal ON memory_routing_log (goal_id, created_at);
CREATE INDEX IF NOT EXISTS idx_memory_routing_log_source ON memory_routing_log (source_conversation_id, created_at);
CREATE TABLE IF NOT EXISTS claim_router_watermark (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    event_id TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS outreach_probe_log (
    id TEXT PRIMARY KEY,
    goal_id TEXT NOT NULL,
    message_id TEXT NOT NULL,           -- messages.id of the inbound message
    verdict TEXT NOT NULL,              -- satisfied|not_satisfied|error
    note TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    UNIQUE(goal_id, message_id)
);
CREATE INDEX IF NOT EXISTS idx_outreach_probe_log_goal ON outreach_probe_log (goal_id, created_at);
CREATE TABLE IF NOT EXISTS outreach_detector_watermark (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    event_id TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "approvals" (
    id TEXT PRIMARY KEY,
    approval_type TEXT NOT NULL CHECK(approval_type IN ('project_plan', 'strategy_refinement', 'task_creation', 'follow_up_tasks', 'purchase', 'group_send', 'conversation_steer')),
    entity_id TEXT NOT NULL,  -- ID of the thing needing approval (goal_id, etc.)
    title TEXT NOT NULL,
    description TEXT,
    proposal_data TEXT,  -- JSON string containing the full proposal (e.g. the merch cart, or a steering instruction + rendered wake)
    status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'rejected', 'cancelled')),
    priority TEXT DEFAULT 'normal' CHECK(priority IN ('low', 'normal', 'high', 'urgent')),
    requested_at TEXT NOT NULL,
    requested_by TEXT,  -- User or system that requested approval
    reviewed_at TEXT,
    reviewed_by TEXT,
    review_notes TEXT,
    metadata TEXT,  -- Additional JSON data (e.g. origin_conversation_id for the gate wake)
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_approvals_status ON approvals(status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_approvals_type ON approvals(approval_type, status);
CREATE INDEX IF NOT EXISTS idx_approvals_entity ON approvals(entity_id, approval_type);
CREATE INDEX IF NOT EXISTS idx_approvals_requested_at ON approvals(requested_at DESC);
CREATE VIEW IF NOT EXISTS pending_approvals AS
SELECT
    id,
    approval_type,
    entity_id,
    title,
    description,
    proposal_data,
    priority,
    requested_at,
    requested_by,
    created_at
FROM approvals
WHERE status = 'pending'
ORDER BY
    CASE priority
        WHEN 'urgent' THEN 1
        WHEN 'high' THEN 2
        WHEN 'normal' THEN 3
        WHEN 'low' THEN 4
    END,
    requested_at ASC;

